#include <stdio.h>
#include "kit.h"
#include "kit_label.h"

static int read_digit(void)
{
    int symbol = getchar();
    if (symbol < '0' || symbol > '9') {
        return -1;
    }
    int tail = getchar();
    return tail == '\n' || tail == EOF ? symbol - '0' : -1;
}

int main(void)
{
    int kits = read_digit();
    if (kits < 0) {
        puts("invalid");
        return 1;
    }
    struct Kit order = {kits * PARTS_PER_KIT};
    printf("parts=%d\n", order.parts);
    return 0;
}

